<script>
import { adminApi } from "../../services/adminApi";
export default { data(){return {loading:true,error:"",items:[]}}, async mounted(){try{this.items=await adminApi.get("subscriptions")}catch(e){this.error=e.response?.data?.message||"Não foi possível carregar os dados."}finally{this.loading=false}}, methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},date(v){return v?new Date(v).toLocaleDateString("pt-BR"):"—"}}}
</script><template><div><h4>Assinaturas SaaS</h4><p class="text-muted">Acompanhamento das assinaturas dos músicos.</p><div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Músico</th><th>Plano</th><th>Valor</th><th>Pagamento</th><th>Início</th><th>Fim</th><th>Status</th></tr></thead><tbody><tr v-for="x in items" :key="x.id"><td><strong>{{x.tenantName}}</strong><div class="small text-muted">{{x.tenantEmail}}</div></td><td>{{x.planName}}</td><td>{{money(x.monthlyFee)}}</td><td>{{x.paymentMethod}}</td><td>{{date(x.startDate)}}</td><td>{{date(x.endDate)}}</td><td><span class="badge bg-primary-subtle text-primary">{{x.status}}</span></td></tr></tbody></table></div></div></div></template>